test invoice.queue-reminder-once/existing-custom-marker {
    file::write("outbox/invoice-reminders/r2-existing-custom-fix", "custom reminder marker");
    invoice::queue-reminder-once(invoice::new(InvoiceId::new("r2-existing-custom-fix"), InvoiceStatus::new("open"))) => "custom reminder marker"
}

test invoice.queue-reminder-once/existing-marker-not-rewritten {
    file::write("outbox/invoice-reminders/r2-existing-no-rewrite", "leave this marker");
    let first = invoice::queue-reminder-once(invoice::new(InvoiceId::new("r2-existing-no-rewrite"), InvoiceStatus::new("open")));
    let second = invoice::queue-reminder-once(invoice::new(InvoiceId::new("r2-existing-no-rewrite"), InvoiceStatus::new("open")));
    file::read("outbox/invoice-reminders/r2-existing-no-rewrite") => "leave this marker"
}
